insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id from jsonb_to_recordset($bank$[{"id":"che-pe-268","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Effective nuclear charge experienced by a valence electron is written $Z_{\\mathrm{eff}}=Z-\\sigma$, where $\\sigma$ is the","options":["atomic mass","screening constant","mass number","group number"],"answer_index":1,"explanation":"Inner electrons cancel part of Z; the remainder is the effective nuclear charge felt by the outer electron.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general"},{"id":"che-pe-269","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Inner electrons shield valence electrons from the full attraction of the","options":["neighbouring atoms","nucleus","neutron cloud","crystal field"],"answer_index":1,"explanation":"Screening (shielding) is the reason Zeff is smaller than Z.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general"},{"id":"che-pe-270","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Effective nuclear charge felt by the outermost electron","options":["falls across a period","increases across a period","is zero for all metals","equals the mass number"],"answer_index":1,"explanation":"Electrons are added to the same shell, which screens poorly, so Zeff climbs left to right.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general"},{"id":"che-pe-271","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Down a group, the increase in shielding and the addition of shells outweigh the rise in nuclear charge, so","options":["atomic size shrinks","atomic size grows","IE rises sharply","all elements become noble gases"],"answer_index":1,"explanation":"The net result is a larger, more loosely held valence electron in the heavier congener.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general"},{"id":"che-pe-272","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In a given period, a smaller atomic size is generally accompanied by a","options":["smaller ionisation enthalpy","larger ionisation enthalpy","negative nuclear charge","new f subshell"],"answer_index":1,"explanation":"The outer electron is closer to the nucleus and harder to remove in the smaller atom.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general"},{"id":"che-pe-273","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Non-metallic character increases from left to right across a","options":["group","period","set of alkali metals","lanthanoid contraction pair"],"answer_index":1,"explanation":"IE and electronegativity rise, so the tendency to gain or share electrons grows.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general"},{"id":"che-pe-274","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Melting points, boiling points and densities of elements also display","options":["no variation with Z","periodic variation","a linear fall with mass number only","identical values in every group"],"answer_index":1,"explanation":"These bulk properties repeat in a rough pattern because bonding type and size are themselves periodic.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general"},{"id":"che-pe-275","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"s-block elements are strongly electropositive metals, except for","options":["sodium and potassium","hydrogen and helium","calcium and barium","all of group 2"],"answer_index":1,"explanation":"H and He are non-metals placed in period 1; the rest of the s-block are typical metals.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general"},{"id":"che-pe-276","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The p-block is the only block that contains metals, metalloids and non-metals in the","options":["s-block groups","same set of groups","f-block rows","first period alone"],"answer_index":1,"explanation":"Group 14, for example, runs from non-metal C through metalloid Si/Ge to metals Sn and Pb.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general"},{"id":"che-pe-277","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Screening of the nuclear charge is poorer by d and f electrons than by","options":["the nucleus itself","s and p electrons of the same shell","neutrons","alpha particles"],"answer_index":1,"explanation":"Penetrating s (and p) electrons cancel Z more effectively; d and f electrons leave a higher Zeff on the outside.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general"},{"id":"che-pe-278","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Neon has both a very small covalent radius and the highest first ionisation enthalpy of","options":["period 3","period 2","the alkali metals","the lanthanoids"],"answer_index":1,"explanation":"Closed-shell compactness and maximum Zeff in that row make Ne the extreme of both trends.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periodic-trends-general"},{"id":"che-pe-279","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"From lithium to caesium, ionisation enthalpy falls while atomic radius rises, so the two trends reinforce the","options":["decrease in metallic character","increase in metallic character","rise of electronegativity","formation of noble gases"],"answer_index":1,"explanation":"A larger, more loosely held ns¹ electron makes the heavier alkali metal more metallic.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periodic-trends-general"},{"id":"che-pe-280","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fluorine is more electronegative than chlorine, yet chlorine has the more negative electron gain enthalpy — a pair of trends that","options":["always run in step","do not run in step","apply only to metals","forbid any F–Cl bond"],"answer_index":1,"explanation":"χ follows size/Zeff, while ΔegH of F is reduced by 2p–2p repulsion; the two properties therefore order F and Cl differently.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periodic-trends-general"},{"id":"che-pe-281","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Na⁺ and neon are isoelectronic, but Na⁺ has the higher ionisation enthalpy because of its","options":["smaller nuclear charge","greater nuclear charge","extra 3s electron","f-block contraction"],"answer_index":1,"explanation":"Both have 10 electrons; Z(Na⁺) = 11 > Z(Ne) = 10, so the Na⁺ cloud is more tightly bound.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periodic-trends-general"},{"id":"che-pe-282","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The first ionisation enthalpy of gallium is slightly higher than that of aluminium because the poorly shielding 3d¹⁰ electrons","options":["lower Zeff on Ga","raise Zeff on Ga","remove the 4p electron","turn Ga into an alkali metal"],"answer_index":1,"explanation":"d-block contraction increases Zeff and offsets the expected fall of IE down group 13.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periodic-trends-general"},{"id":"che-pe-283","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Oxygen is smaller than nitrogen, which would suggest a higher IE for O, yet IE of O is lower than that of N because","options":["oxygen has a half-filled 2p³ set","the paired 2p⁴ electron of oxygen is easier to remove","nitrogen has the larger nuclear charge","oxygen lacks a 2s pair"],"answer_index":1,"explanation":"The size trend and the pairing-repulsion trend oppose each other; pairing wins, so IE(N) > IE(O).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"periodic-trends-general"},{"id":"che-pe-284","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Size decreases from Be to B, which would suggest a higher IE for B; the observed lower IE of B is due to","options":["the ease of removing the 2p electron compared with Be 2s²","a fall in nuclear charge from Be to B","boron having a closed 2p⁶ shell","beryllium being a halogen"],"answer_index":0,"explanation":"Again two trends conflict: smaller radius would raise IE, but the change of subshell (2s → 2p) lowers it.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"periodic-trends-general"},{"id":"che-so-101","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A homogeneous mixture whose composition is uniform at the molecular scale is called a","options":["compound with fixed mass ratio only","solution","coarse suspension","heterogeneous colloid only"],"answer_index":1,"explanation":"A solution is a single-phase homogeneous mixture of solute and solvent.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"types-solubility"},{"id":"che-so-102","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Ordinary air is best classified as a solution of the type","options":["gas dissolved in a liquid","gas mixed with gas","liquid droplets in a gas","solid smoke in a gas"],"answer_index":1,"explanation":"Nitrogen, oxygen and the other constituents form a gaseous solution.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"types-solubility"},{"id":"che-so-103","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Brass (copper plus zinc) is a textbook example of a","options":["liquid–liquid blend","gas–solid hydride","solid–solid alloy solution","gas–liquid soda"],"answer_index":2,"explanation":"Alloys such as brass are solid solutions of metals in metals.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"types-solubility"}]$bank$::jsonb) as t(id text, chapter_id text, subject_id text, stem text, options jsonb, answer_index int, explanation text, images jsonb, source jsonb, difficulty text, concept_id text) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
